static void N_imp45(double* restrict dst, const double* restrict src){
  for (long xx=0; xx<45; xx++)
    for (long y=0; y<45; y++)
      memcpy(dst + (xx*2164 + y*48)*2, src + (xx*2025 + y*45)*2, 45*16);
}
static void N_exp45(double* restrict dst, const double* restrict src){
  for (long xx=0; xx<45; xx++)
    for (long y=0; y<45; y++)
      memcpy(dst + (xx*2025 + y*45)*2, src + (xx*2164 + y*48)*2, 45*16);
}
